import { useImmer } from 'use-immer';

export default function App() {
  const [state, setState] = useImmer({
    count: 0,
    name: 'Joe'
  })

  const handleClick = () => {
    setState(draft => {
      draft.count += 1
    })
    console.log(state)
  }

