Golang 中，类实现了接口中的所有方法，就实现了这个接口。

```go
package main

import "fmt"

// 本质是一个指针
type AnimalIF interface {
	Sleep()
	GetColor() string // 获取动物的颜色
	GetType() string // 获取动物的种类
}

// 具体的类
type Cat struct {
	color string // 猫的颜色
}
// 实现接口中的方法
func (this *Cat) Sleep() {
	fmt.Println("Cat.Sleep()...")
}
func (this *Cat) GetColor() string {
	fmt.Println("Cat.GetColor()...")
	return this.color
}
func (this *Cat) GetType() string {
	fmt.Println("Cat.GetType()...")
	return "Cat"
}

// 具体的类
type Dog struct {
	color string
}
// 实现接口中的方法
func (this *Dog) Sleep() {
	fmt.Println("Dog.Sleep()...")
}
func (this *Dog) GetColor() string {
	fmt.Println("Dog.GetColor()...")
	return this.color
}
func (this *Dog) GetType() string {
	fmt.Println("Dog.GetType()...")
	return "Dog"
}

func showAnimal(animal AnimalIF) {
	animal.Sleep() // 多态
	fmt.Println("color =", animal.GetColor())
	fmt.Println("kind =", animal.GetType())
}

func main() {
	var animal AnimalIF // 父类型引用指向子类型对象
	animal = &Dog{"红色"} // 多态
	animal.Sleep()

	animal = &Cat{"黑色"} // 多态
	animal.Sleep()

	cat := Cat{"绿色"}
	dog := Dog{"白色"}
	showAnimal(&cat)
	showAnimal(&dog)
}

```

以上就通过接口，实现了go语言中的多态。父类型引用指向子类型对象。

这些都和Java中的多态机制的概念和作用基本保持一致，只是实现方式有了区别。

### interface 空接口通用万能类型

空接口：`interface{}`

int、string、float32、float64、struct... 都实现了 `interface{}`，根据多态机制，`interface{}` 类型 引用 任意的数据类型。（这就类似于Java中的 Object 对象）

```go
package main

import "fmt"

// interface{} 是万能数据类型
func myFunc(arg interface{}) {
	fmt.Println("myFunc is called...")
	fmt.Println(arg)

	// interface{} 提供 “类型断言” 机制
	value, ok := arg.(string)
	if !ok {
		fmt.Println("arg is not string type")
		fmt.Println("============\n")
	} else {
		fmt.Println("arg is string type, value =", value)
		fmt.Printf("arg type is %T\n", arg)
		fmt.Printf("value type is %T\n", value)
		fmt.Println("============\n")
	}
}

type Book struct {
	auth string
}

func main() {
	book := Book{"Golang"}
	myFunc(book)
	myFunc(100)
	myFunc(3.14)
	myFunc("gantoho")
}

```

