    public void attackAll() {
        // 遍历数组
        for (int i = 0; i < weapons.length; i++) {
            if(weapons[i] instanceof Shootable) {
                // 调用子类中特有的方法，向下转型。
                Shootable shootable = (Shootable) weapons[i];
                shootable.shoot();
            }
        }
    }
    /**
     * 所有可移动的武器移动
     */
    public void moveAll() {
        // 遍历数组
        for (int i = 0; i < weapons.length; i++) {
            if(weapons[i] instanceof Moveable) {
                // 调用子类中特有的方法，向下转型。
                Moveable moveable = (Moveable) weapons[i];
                moveable.move();
            }
        }
    }
}

