以下两种写法完全一样。

```typescript
// 定义一个表示人的类
class Person{
  public name: String;
  constructor(name: String) {
    this.name = name;
  }
}

const per = new Person("红孩儿");
console.log(per.name);


```

```typescript
// 定义一个表示人的类
class Person{
  constructor(public name: String) {}
}

const per = new Person("红孩儿");
console.log(per.name);

